#!/usr/bin/env node
/**
 * tecton — look up @tecton/react components from a terminal or a coding agent.
 *
 *   tecton search <what the UI must do>   ranked components, their import and boundaries
 *   tecton docs <id|Component>[,…]        the usage guideline: Use it when, Not for, Do, Don't
 *   tecton list [--family <name>]         every id with a one-line summary
 *   tecton rules                          the rules every file follows (= tecton docs rules)
 *
 * Reads agent/index.json and agent/docs/*.md, generated by
 * `pnpm --filter @tecton/react agent:build`. Plain Node, no dependencies:
 * it ships in the package and runs from an application's node_modules.
 */
import { existsSync, readFileSync, realpathSync } from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"

const PKG_ROOT = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  ".."
)
const AGENT_DIR = path.join(PKG_ROOT, "agent")

// ---------------------------------------------------------------------------
// text
// ---------------------------------------------------------------------------

const STOPWORDS = new Set(
  (
    "a an and are as at be but by can do for from has have how i if in into is it its of on or " +
    "so that the their them then there these this to use used using want we when where which " +
    "with without you your need needs needed show shows showing display make build add let lets " +
    "should one some something thing things component components tecton react ui page user users"
  ).split(" ")
)

/**
 * A light suffix stripper: enough to meet "wells"/"well", "loading"/"load",
 * "resize"/"resizable", "collapse"/"collapsible".
 */
export function stem(word) {
  let root = word
  if (root.length > 4 && root.endsWith("ies")) root = `${root.slice(0, -3)}y`
  else if (root.length > 5 && root.endsWith("ing")) root = root.slice(0, -3)
  else if (root.length > 4 && root.endsWith("ed")) root = root.slice(0, -2)
  else if (root.length > 3 && /(ss|us|is)$/.test(root)) return root
  else if (root.length > 3 && /(ches|shes|xes|ses)$/.test(root))
    root = root.slice(0, -2)
  else if (root.length > 3 && root.endsWith("s")) root = root.slice(0, -1)
  if (root.length > 7 && /[ai]ble$/.test(root)) root = root.slice(0, -4)
  if (root.length > 4 && root.endsWith("e")) root = root.slice(0, -1)
  return root
}

export function tokenize(text) {
  return String(text)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .split(" ")
    .filter((word) => word && !STOPWORDS.has(word))
    .map(stem)
}

// ---------------------------------------------------------------------------
// the index
// ---------------------------------------------------------------------------

/** Field weights for BM25F: a name match beats a mention in a Do bullet. */
const WEIGHTS = { names: 3, routed: 2, useWhen: 1.5, do: 0.6 }
const K1 = 1.2
const B = 0.6
/** Weight of a word that came from synonyms.json rather than from the query. */
const SYNONYM_WEIGHT = 0.7

export function loadIndex(dir = AGENT_DIR) {
  const file = path.join(dir, "index.json")
  if (!existsSync(file)) {
    throw new Error(
      `tecton: ${file} is missing — run \`pnpm --filter @tecton/react agent:build\``
    )
  }
  const index = JSON.parse(readFileSync(file, "utf8"))
  const fields = Object.keys(WEIGHTS)
  const docs = index.entries.map((entry) => {
    const tf = {}
    const length = {}
    for (const field of fields) {
      const words = tokenize(entry.fields[field] ?? "")
      length[field] = words.length
      const counts = new Map()
      for (const word of words) counts.set(word, (counts.get(word) ?? 0) + 1)
      tf[field] = counts
    }
    return { entry, tf, length }
  })
  const avg = {}
  for (const field of fields) {
    avg[field] =
      docs.reduce((sum, doc) => sum + doc.length[field], 0) / docs.length || 1
  }
  const df = new Map()
  for (const doc of docs) {
    const seen = new Set()
    for (const field of fields)
      for (const word of doc.tf[field].keys()) seen.add(word)
    for (const word of seen) df.set(word, (df.get(word) ?? 0) + 1)
  }
  const synonyms = new Map()
  for (const [word, targets] of Object.entries(index.synonyms ?? {})) {
    synonyms.set(stem(word), targets.map(stem))
  }
  const byKey = new Map()
  for (const entry of index.entries) {
    byKey.set(entry.id.toLowerCase(), entry.id)
    byKey.set(entry.name.toLowerCase(), entry.id)
    for (const name of [...entry.exports, ...(entry.aliases ?? [])]) {
      if (!byKey.has(name.toLowerCase()))
        byKey.set(name.toLowerCase(), entry.id)
    }
  }
  return { ...index, dir, docs, avg, df, synonyms, byKey }
}

/** Query words with their weights: the words typed, then their synonyms. */
function expand(query, index, useSynonyms) {
  const terms = new Map()
  for (const word of tokenize(query)) terms.set(word, 1)
  if (!useSynonyms) return terms
  for (const word of [...terms.keys()]) {
    for (const target of index.synonyms.get(word) ?? []) {
      if (!terms.has(target)) terms.set(target, SYNONYM_WEIGHT)
    }
  }
  return terms
}

/**
 * BM25F over the entry fields. `weights` and `synonyms` exist for the eval's
 * ablations (agent-eval/search-eval.mjs); the CLI always uses the defaults.
 */
export function search(
  index,
  query,
  { limit = 5, weights = WEIGHTS, synonyms = true } = {}
) {
  const terms = expand(query, index, synonyms)
  const total = index.docs.length
  const results = []
  for (const doc of index.docs) {
    let score = 0
    for (const [term, weight] of terms) {
      const df = index.df.get(term)
      if (!df) continue
      let tf = 0
      for (const [field, fieldWeight] of Object.entries(weights)) {
        if (!fieldWeight) continue
        const count = doc.tf[field].get(term)
        if (!count) continue
        tf +=
          (fieldWeight * count) /
          (1 - B + (B * doc.length[field]) / index.avg[field])
      }
      if (!tf) continue
      const idf = Math.log(1 + (total - df + 0.5) / (df + 0.5))
      score += weight * idf * ((tf * (K1 + 1)) / (tf + K1))
    }
    if (score > 0) results.push({ entry: doc.entry, score })
  }
  results.sort(
    (a, b) => b.score - a.score || a.entry.id.localeCompare(b.entry.id)
  )
  return results.slice(0, limit)
}

/** Resolves `alert-dialog`, `AlertDialog` or `AlertDialogAction` to an id. */
export function resolveId(index, key) {
  return index.byKey.get(String(key).trim().toLowerCase()) ?? null
}

export function readDoc(index, id) {
  return readFileSync(path.join(index.dir, "docs", `${id}.md`), "utf8").replace(
    /^<!--.*-->\n\n/,
    ""
  )
}

// ---------------------------------------------------------------------------
// output
// ---------------------------------------------------------------------------

function formatTokens(tokens) {
  return tokens >= 1000 ? `${(tokens / 1000).toFixed(1)}k` : String(tokens)
}

function truncate(text, max) {
  const flat = text.replace(/`/g, "").replace(/\s+/g, " ").trim()
  return flat.length > max ? `${flat.slice(0, max - 1)}…` : flat
}

function renderSearch(query, results) {
  if (!results.length) {
    return `No match for "${query}". Try other words, or \`tecton list\` to browse every component.`
  }
  const lines = []
  results.forEach(({ entry }, at) => {
    const where =
      entry.kind === "topic"
        ? "topic"
        : (entry.import?.match(/from "([^"]+)"/)?.[1] ?? "")
    lines.push(
      `${at + 1}. ${entry.id} — ${entry.name} — ${where} — ≈${formatTokens(entry.tokens)} tok`
    )
    lines.push(`   ${truncate(entry.summary, 140)}`)
    if (entry.notFor.length) {
      const boundaries = entry.notFor
        .slice(0, 3)
        .map((item) => `${truncate(item.need, 60)} → ${item.id}`)
      lines.push(`   not for: ${boundaries.join("; ")}`)
    }
  })
  lines.push(
    "",
    `Next: tecton docs ${results[0].entry.id}${results[1] ? ` (or ${results[1].entry.id})` : ""}`
  )
  return lines.join("\n")
}

function renderList(entries) {
  return entries
    .map(
      (entry) =>
        `${entry.id} — ${entry.name}${entry.family ? ` [${entry.family}]` : ` [${entry.kind}]`} — ${truncate(entry.summary, 90)}`
    )
    .join("\n")
}

const HELP = `tecton — look up @tecton/react components

  tecton search <what the UI must do>   ranked components with import and boundaries
  tecton docs <id|Component>[,…]        usage guideline: Use it when, Not for, Do, Don't
  tecton list [--family <name>]         every id with a one-line summary
  tecton rules                          the rules every file follows

Options: --json (search, list), --limit <n> (search, default 5)`

// ---------------------------------------------------------------------------
// main
// ---------------------------------------------------------------------------

function option(args, flag) {
  const at = args.indexOf(flag)
  if (at === -1) return undefined
  const value = args[at + 1]
  args.splice(at, 2)
  return value
}

export function run(argv, index = loadIndex()) {
  const args = [...argv]
  const json = args.includes("--json")
  if (json) args.splice(args.indexOf("--json"), 1)
  const command = args.shift()

  if (
    !command ||
    command === "help" ||
    command === "--help" ||
    command === "-h"
  ) {
    return { code: 0, out: HELP }
  }

  if (command === "search") {
    const limit = Number(option(args, "--limit") ?? 5)
    const query = args.join(" ").trim()
    if (!query)
      return {
        code: 1,
        out: 'tecton search: say what the UI must do, e.g. tecton search "confirm before deleting"',
      }
    const results = search(index, query, { limit })
    if (json) {
      return {
        code: 0,
        out: JSON.stringify(
          results.map(({ entry, score }) => ({
            id: entry.id,
            name: entry.name,
            kind: entry.kind,
            import: entry.import,
            summary: entry.summary,
            notFor: entry.notFor,
            tokens: entry.tokens,
            score: Number(score.toFixed(3)),
          })),
          null,
          2
        ),
      }
    }
    return { code: 0, out: renderSearch(query, results) }
  }

  if (command === "docs" || command === "rules") {
    const keys =
      command === "rules"
        ? ["rules"]
        : args
            .join(",")
            .split(",")
            .map((key) => key.trim())
            .filter(Boolean)
    if (!keys.length)
      return {
        code: 1,
        out: "tecton docs: name one or more ids, e.g. tecton docs select,combobox",
      }
    const out = []
    let code = 0
    for (const key of keys) {
      const id = resolveId(index, key)
      if (id) {
        out.push(readDoc(index, id).trimEnd())
        continue
      }
      code = 1
      const guesses = search(index, key, { limit: 3 }).map(
        ({ entry }) => entry.id
      )
      out.push(
        `No entry "${key}".${guesses.length ? ` Did you mean: ${guesses.join(", ")}?` : ""}`
      )
    }
    return { code, out: out.join("\n\n---\n\n") }
  }

  if (command === "list") {
    const family = option(args, "--family")
    const entries = index.entries.filter(
      (entry) => !family || entry.family === family
    )
    if (json) {
      return {
        code: 0,
        out: JSON.stringify(
          entries.map(({ id, name, kind, family: group, summary }) => ({
            id,
            name,
            kind,
            family: group,
            summary,
          })),
          null,
          2
        ),
      }
    }
    return { code: 0, out: renderList(entries) }
  }

  return { code: 1, out: `tecton: unknown command "${command}"\n\n${HELP}` }
}

// node_modules/.bin/tecton is a symlink (or a shim) to this file.
const invokedDirectly = (() => {
  try {
    return (
      fileURLToPath(import.meta.url) === realpathSync(process.argv[1] ?? "")
    )
  } catch {
    return false
  }
})()

if (invokedDirectly) {
  try {
    const { code, out } = run(process.argv.slice(2))
    process.stdout.write(`${out}\n`)
    process.exitCode = code
  } catch (error) {
    process.stderr.write(`${error.message}\n`)
    process.exitCode = 1
  }
}
